import json
src=json.load(open('tr/p7-in-ru.json'))
T={
src[0]:"Бесплатный калькулятор импортных пошлин Индии: ищите среди {0}+ тарифных позиций HSN по коду или описанию, выбирайте страну происхождения и смотрите BCD, сбор на социальное обеспечение, IGST, полную стоимость с доставкой и импортную политику DGFT.",
src[1]:". Саудовская Аравия пересмотрела тариф в декабре {0}, и эти данные ({1}) могут этого не отражать. НДС {2}% взимается с CIF плюс пошлина.",
src[2]:"Ставки — это общая импортная пошлина (IGI) по применяемому тарифу World Bank WITS, данные за {0}. В данных используется более старая нумерация ТН ВЭД, поэтому некоторые актуальные коды HS {1} указаны под прежним кодом (например, смартфоны — под {2}). Если тарифные позиции внутри одного кода HS различаются, показывается диапазон и используется наибольшая ставка. Таможенный сбор за оформление (DTA) добавляется в размере {3}% от таможенной стоимости, а IVA в размере {4}% взимается с таможенной стоимости плюс IGI плюс DTA. Для товаров из стран, с которыми действуют соглашения о свободной торговле (например, USMCA), применяются пониженные ставки и фиксированный DTA; здесь они не учитываются. Акциз IEPS и антидемпинговые пошлины не включены. Уточняйте на",
src[3]:"Машины и приборы для испытания твёрдости, прочности, сжимаемости, упругости или других механических свойств материалов (например, металлов, древесины, текстиля, бумаги, пластмасс)",
src[4]:"Части респираторных аппаратов и противогазов, предназначенные для некоторых типов воздушных судов",
src[5]:"Пошлина взимается со стоимости CIF. Импортный НДС взимается с CIF плюс пошлина по ставке того государства-члена, где выпускаются товары. Выберите государство.",
src[6]:"Пошлина взимается с таможенной стоимости, то есть стоимости товаров без международной перевозки и страхования. GST в размере {0}% взимается со стоимости облагаемого импорта: товары, пошлина, международная перевозка и страхование. Отправления стоимостью AUD {1} или меньше обычно обрабатываются иначе.",
src[7]:"Сингапур — свободный порт. Пошлина взимается только с алкоголя, табака, автомобилей и нефтепродуктов. Всё остальное не облагается пошлиной, а GST в размере {0}% взимается со стоимости CIF.",
src[8]:"Пошлина применяется только к алкоголю, табаку, автомобилям и нефтепродуктам. Для таких товаров калькулятор не может дать точную сумму, поэтому обратитесь к брокеру. Для всех остальных товаров пошлина равна нулю, а GST в размере {0}% взимается со стоимости CIF.",
src[9]:". НДС {0}% взимается с CIF плюс пошлина.",
}
for s in src[10:]:
    if s in T: continue
    if "per {1}" in s:
        cur=s.split("} ")[1].split(" (")[0]  # "{1} JPY"
        T[s]=": ₹{0} за {1} "+cur.split()[-1]+" (экспортный курс ₹{2}). Уведомление о курсе валют № {3}/{4}, действует с {5}. Таможня применяет курс, действующий на дату подачи таможенной декларации (bill of entry). Вы можете изменить этот курс."
    else:
        c=s.split(" per ")[1][:3]
        T[s]=": ₹{0} за 1 "+c+" (экспортный курс ₹{1}). Уведомление о курсе валют № {2}/{3}, действует с {4}. Таможня применяет курс, действующий на дату подачи таможенной декларации (bill of entry). Вы можете изменить этот курс."
assert len(T)==len(src)
json.dump(T,open('tr/p7-out-ru.json','w'),ensure_ascii=False,indent=1)
